function PlaybackProgress({ clock, onSeek }: { clock: PlaybackClock; onSeek: (fraction: number) => void }) {
  const snapshot = usePlaybackClock(clock);
  return <><input aria-label="å½“å‰å¥æ’­æ”¾è¿›åº¦" className="seek-range" type="range" min="0" max="100" value={snapshot.durationMs ? snapshot.elapsedMs / snapshot.durationMs * 100 : 0} onChange={(event) => onSeek(Number(event.target.value) / 100)} /><span className="time-readout">{formatTime(snapshot.elapsedMs)} / {formatTime(snapshot.durationMs)}</span></>;
}

function formatTime(milliseconds: number) {
  const seconds = Math.max(0, milliseconds) / 1000;
  return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(Math.floor(seconds % 60)).padStart(2, '0')}.${Math.floor(seconds * 10) % 10}`;
}


function AiReviewDialog({ state, busy, selectedGroupCount, onCancel, onExport, onApply, onCopyPrompt, onToggle }: {
  state: AiReviewState;
  busy: boolean;
  selectedGroupCount: number;
  onCancel: () => void;
  onExport: (options: { scopeType: 'project' | 'chapter' | 'groups'; includeMedia: boolean; goal: string }) => void;
  onApply: (selectedIndexes: number[]) => void;
  onCopyPrompt: (prompt: string) => void;
  onToggle: (index: number, checked: boolean) => void;
}) {
  if (state.mode === 'export') return <AiReviewExportDialog state={state} busy={busy} selectedGroupCount={selectedGroupCount} onCancel={onCancel} onExport={onExport} />;
  if (state.mode === 'prompt') return <div className="name-dialog-overlay"><section className="ai-review-dialog prompt-dialog" role="dialog" aria-modal="true" aria-labelledby="ai-prompt-title"><h2 id="ai-prompt-title">å®¡é˜…åŒ…å·²å¯¼å‡º</h2><p>æ–‡ä»¶å·²ä¿å­˜åˆ°æœ¬æœºã€‚å¤åˆ¶ä¸‹é¢æç¤ºè¯åˆ°ä½ ä½¿ç”¨çš„ AIï¼Œå†æŠŠè¿”å›çš„ JSON å»ºè®®æ–‡ä»¶å¯¼å›è½¯ä»¶ã€‚</p><small className="ai-review-path">{state.filePath}</small><textarea readOnly value={state.prompt} onFocus={(event) => event.currentTarget.select()} aria-label="å¯å¤åˆ¶çš„ AI æ”¹è¿›æç¤ºè¯" /><div className="name-dialog-actions"><button className="button quiet" onClick={onCancel}>å…³é—­</button><button className="button primary" onClick={() => onCopyPrompt(state.prompt)}>å¤åˆ¶æç¤ºè¯</button></div></section></div>;
  const selectedIndexes = state.proposal.changes.map((_change: any, index: number) => state.checked[index] ? index : -1).filter((index: number) => index >= 0);
  return <div className="name-dialog-overlay"><section className="ai-review-dialog" role="dialog" aria-modal="true" aria-labelledby="ai-review-title"><h2 id="ai-review-title">æ£€æŸ¥ AI æ”¹è¿›å»ºè®®</h2><p className="ai-review-subtitle">{state.fileName} Â· å·²é€šè¿‡å·¥ç¨‹ IDã€åŸºçº¿å“ˆå¸Œã€ç›®æ ‡ IDã€å‚æ•°å’Œç´ ææ£€æŸ¥ã€‚åªä¼šåº”ç”¨å‹¾é€‰é¡¹ç›®ï¼Œæ•´æ‰¹å¯ä¸€æ¬¡æ’¤é”€ã€‚</p><div className="ai-review-change-list">{state.proposal.changes.length ? state.proposal.changes.map((change: any, index: number) => <AiReviewChangeCard key={`${change.op}-${change.chapterId}-${change.cueId ?? change.groupIds.join(',')}`} change={change} checked={state.checked[index]} onToggle={(checked) => onToggle(index, checked)} />) : <div className="ai-review-empty">æ–‡ä»¶åŸºçº¿æœ‰æ•ˆï¼Œä½†æ²¡æœ‰æ”¹è¿›å»ºè®®å¯åº”ç”¨ã€‚</div>}</div><div className="name-dialog-actions"><button className="button quiet" disabled={busy} onClick={onCancel}>å–æ¶ˆ</button><button className="button primary" disabled={busy || !selectedIndexes.length} onClick={() => onApply(selectedIndexes)}>{busy ? 'æ­£åœ¨åº”ç”¨â€¦' : `åº”ç”¨å‹¾é€‰é¡¹ï¼ˆ${selectedIndexes.length}ï¼‰`}</button></div></section></div>;
}

